import{_ as e,o,c as r,ag as a}from"./chunks/framework.Cyu1VozZ.js";const p=JSON.parse('{"title":"Writing a Document","description":"","frontmatter":{},"headers":[],"relativePath":"docs-editor/writing-a-document.md","filePath":"docs-editor/writing-a-document.md"}'),n={name:"docs-editor/writing-a-document.md"};function s(i,t,l,d,h,g){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="writing-a-document" tabindex="-1">Writing a Document <a class="header-anchor" href="#writing-a-document" aria-label="Permalink to &quot;Writing a Document&quot;">​</a></h1><p>This guide covers creating and editing documents in Wafflebase — a word-processor-style editor with real-time collaboration.</p><h2 id="create-a-document" tabindex="-1">Create a Document <a class="header-anchor" href="#create-a-document" aria-label="Permalink to &quot;Create a Document&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>New Document</strong></li></ol><p>A blank document opens with a page-style layout, similar to Google Docs.</p><h2 id="basic-editing" tabindex="-1">Basic Editing <a class="header-anchor" href="#basic-editing" aria-label="Permalink to &quot;Basic Editing&quot;">​</a></h2><p>Click anywhere on the page to place your cursor and start typing. The editor works like a standard word processor:</p><ul><li><strong>Enter</strong> — Split into a new paragraph</li><li><strong>Backspace / Delete</strong> — Remove characters</li><li><strong>Arrow keys</strong> — Move the cursor</li><li>Text wraps automatically at the page edge</li></ul><h3 id="select-text" tabindex="-1">Select Text <a class="header-anchor" href="#select-text" aria-label="Permalink to &quot;Select Text&quot;">​</a></h3><ul><li><strong>Click and drag</strong> to select a range of text</li><li><strong>Double-click</strong> to select a word</li><li><strong>Triple-click</strong> to select a paragraph</li><li><strong>⌘+A</strong> / <strong>Ctrl+A</strong> to select all text</li></ul><h3 id="copy-cut-and-paste" tabindex="-1">Copy, Cut, and Paste <a class="header-anchor" href="#copy-cut-and-paste" aria-label="Permalink to &quot;Copy, Cut, and Paste&quot;">​</a></h3><ul><li><strong>⌘+C</strong> / <strong>Ctrl+C</strong> — Copy selected text</li><li><strong>⌘+X</strong> / <strong>Ctrl+X</strong> — Cut selected text</li><li><strong>⌘+V</strong> / <strong>Ctrl+V</strong> — Paste text</li></ul><p>Paste keeps as much of the original as it can. The editor looks at the clipboard in this order:</p><ol><li><strong>An image</strong> — a screenshot or a picture copied from another app is inserted into the page, even when the clipboard also carries text.</li><li><strong>Content copied from another Wafflebase document</strong> — pasted back with its formatting intact.</li><li><strong>HTML</strong> — text copied from a web page or another word processor keeps its bold, italic, links, headings, and list structure. An HTML <code>&lt;table&gt;</code> becomes a real table.</li><li><strong>Plain text</strong> — a markdown pipe-table (<code>| a | b |</code> with a <code>| --- |</code> separator line) becomes a real table; anything else has each line turned into a separate paragraph.</li></ol><p>Press <strong>⌘+Shift+V</strong> / <strong>Ctrl+Shift+V</strong> to paste as plain text and drop all formatting.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Pasting a table while the cursor is already inside a table fills cells outward from the current one rather than nesting a new table. Rows and columns that would fall outside the existing grid are dropped.</p></div><h2 id="text-formatting" tabindex="-1">Text Formatting <a class="header-anchor" href="#text-formatting" aria-label="Permalink to &quot;Text Formatting&quot;">​</a></h2><p>Use the formatting toolbar at the top or keyboard shortcuts to style your text.</p><h3 id="inline-styles" tabindex="-1">Inline Styles <a class="header-anchor" href="#inline-styles" aria-label="Permalink to &quot;Inline Styles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Style</th><th>Toolbar</th><th>Shortcut</th></tr></thead><tbody><tr><td><strong>Bold</strong></td><td><strong>B</strong> button</td><td>⌘+B / Ctrl+B</td></tr><tr><td><em>Italic</em></td><td><em>I</em> button</td><td>⌘+I / Ctrl+I</td></tr><tr><td><u>Underline</u></td><td>U button</td><td>⌘+U / Ctrl+U</td></tr><tr><td><s>Strikethrough</s></td><td>—</td><td>⌘+Shift+X / Ctrl+Shift+X</td></tr><tr><td>Superscript</td><td>—</td><td>⌘+. / Ctrl+.</td></tr><tr><td>Subscript</td><td>—</td><td>⌘+, / Ctrl+,</td></tr><tr><td>Text color</td><td>Text color swatch</td><td>Pick from the color palette</td></tr><tr><td>Highlight color</td><td>Highlight swatch</td><td>Pick from the color palette</td></tr><tr><td>Clear formatting</td><td>Clear formatting button</td><td>⌘+\\ / Ctrl+\\</td></tr></tbody></table><p>Strikethrough, superscript, and subscript have no toolbar button in the document editor — use the shortcuts.</p><h3 id="font-and-spacing" tabindex="-1">Font and Spacing <a class="header-anchor" href="#font-and-spacing" aria-label="Permalink to &quot;Font and Spacing&quot;">​</a></h3><p>Alongside the style controls, the toolbar carries:</p><ul><li><strong>Font family</strong> — a curated list of fonts, with <strong>More fonts…</strong> to search the full catalog.</li><li><strong>Font size</strong> — type a number or use the <strong>−</strong> / <strong>+</strong> steppers.</li><li><strong>Line spacing</strong> — presets of 1.0, 1.15, 1.5, and 2.0, plus <strong>Custom…</strong> for any value between 0.5 and 10.</li></ul><p>On a phone, font family and size live in the <strong>⋮</strong> overflow menu.</p><h3 id="format-painter" tabindex="-1">Format Painter <a class="header-anchor" href="#format-painter" aria-label="Permalink to &quot;Format Painter&quot;">​</a></h3><p>Copy the formatting of one piece of text onto another without retyping it.</p><ul><li>Put the cursor in text whose formatting you want, then click the <strong>brush</strong> button in the toolbar (or press <strong>⌘+Shift+C</strong> / <strong>Ctrl+Shift+C</strong>). The button stays lit while the formatting is held.</li><li>Select the text to restyle and click the lit button again to apply it. With nothing selected, clicking it again simply drops the copied formatting.</li><li>The keyboard pair is sticky rather than single-use: <strong>⌘+Alt+V</strong> / <strong>Ctrl+Alt+V</strong> applies the held formatting and keeps it, so you can paint several selections in a row.</li></ul><h2 id="paragraph-styles" tabindex="-1">Paragraph Styles <a class="header-anchor" href="#paragraph-styles" aria-label="Permalink to &quot;Paragraph Styles&quot;">​</a></h2><h3 id="headings-and-named-styles" tabindex="-1">Headings and Named Styles <a class="header-anchor" href="#headings-and-named-styles" aria-label="Permalink to &quot;Headings and Named Styles&quot;">​</a></h3><p>The <strong>Styles</strong> dropdown in the toolbar sets the current block&#39;s style — <strong>Normal text</strong>, <strong>Title</strong>, <strong>Subtitle</strong>, and <strong>Heading 1</strong> through <strong>Heading 6</strong>. Headings also have shortcuts: <strong>⌘+Alt+1</strong> … <strong>⌘+Alt+6</strong> / <strong>Ctrl+Alt+1</strong> … <strong>Ctrl+Alt+6</strong>, and <strong>⌘+Alt+0</strong> / <strong>Ctrl+Alt+0</strong> to go back to Normal text. Applying the heading level a block already has toggles it back to a paragraph.</p><p>Styles are redefinable per document. Format some text the way you want it, then open <strong>Styles → Options</strong>:</p><ul><li><strong>Update &#39;Heading 1&#39; to match</strong> (named for whichever style you are on) — redefine that style from the text at the cursor. Every block using the style updates.</li><li><strong>Reset &#39;Heading 1&#39;</strong> — put that one style back to its built-in appearance.</li><li><strong>Reset styles</strong> — put all of them back.</li><li><strong>Save as my default styles</strong> — keep the document&#39;s style set on your account, and <strong>Use my default styles</strong> to apply it to another document.</li></ul><p>On a phone the block styles are listed under <strong>Styles</strong> in the <strong>⋮</strong> overflow menu; the redefine options are desktop only.</p><h3 id="alignment" tabindex="-1">Alignment <a class="header-anchor" href="#alignment" aria-label="Permalink to &quot;Alignment&quot;">​</a></h3><p>Use the alignment dropdown in the toolbar, or the shortcuts:</p><table tabindex="0"><thead><tr><th>Alignment</th><th>Shortcut</th></tr></thead><tbody><tr><td>Left</td><td>⌘+Shift+L / Ctrl+Shift+L</td></tr><tr><td>Center</td><td>⌘+Shift+E / Ctrl+Shift+E</td></tr><tr><td>Right</td><td>⌘+Shift+R / Ctrl+Shift+R</td></tr><tr><td>Justify</td><td>⌘+Shift+J / Ctrl+Shift+J</td></tr></tbody></table><h3 id="lists-and-indent" tabindex="-1">Lists and Indent <a class="header-anchor" href="#lists-and-indent" aria-label="Permalink to &quot;Lists and Indent&quot;">​</a></h3><ul><li><strong>Numbered list</strong> — the list button, or <strong>⌘+Shift+7</strong> / <strong>Ctrl+Shift+7</strong>.</li><li><strong>Bulleted list</strong> — the list button, or <strong>⌘+Shift+8</strong> / <strong>Ctrl+Shift+8</strong>.</li><li><strong>Tab</strong> / <strong>Shift+Tab</strong> inside a list item nests and un-nests it (up to nine levels). On a plain paragraph, Tab does nothing.</li><li><strong>⌘+]</strong> / <strong>⌘+[</strong> (<strong>Ctrl+]</strong> / <strong>Ctrl+[</strong>) increase and decrease the paragraph indent, list or not.</li></ul><h3 id="type-instead-of-clicking" tabindex="-1">Type Instead of Clicking <a class="header-anchor" href="#type-instead-of-clicking" aria-label="Permalink to &quot;Type Instead of Clicking&quot;">​</a></h3><p>A few markdown-style prefixes convert as you type. Type one at the start of an otherwise empty paragraph, then press <strong>Space</strong> — the space is what fires the conversion:</p><ul><li><code>#</code> through <code>######</code> + <strong>Space</strong> — Heading 1 to Heading 6</li><li><code>-</code> or <code>*</code> + <strong>Space</strong> — bulleted list</li><li><code>1.</code> + <strong>Space</strong> — numbered list</li></ul><p>Typing <code>---</code> on its own line and pressing <strong>Enter</strong> inserts a horizontal rule, and a <code>http://</code> or <code>https://</code> address becomes a clickable link as soon as you type a space after it.</p><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><p>Select some text and press <strong>⌘+K</strong> / <strong>Ctrl+K</strong> — or click the <strong>link</strong> button in the toolbar, or right-click and choose <strong>Add link</strong> — then type the address and click <strong>Apply</strong>.</p><p>Put the cursor inside an existing link and a small popover shows the address with buttons to <strong>edit</strong> or <strong>remove</strong> it.</p><h2 id="find-and-replace" tabindex="-1">Find and Replace <a class="header-anchor" href="#find-and-replace" aria-label="Permalink to &quot;Find and Replace&quot;">​</a></h2><ul><li><strong>⌘+F</strong> / <strong>Ctrl+F</strong> opens the find bar. Type to see the match count, then press <strong>Enter</strong> (or <strong>Shift+Enter</strong>) to step forward and back through matches. <strong>Esc</strong> closes the bar.</li><li><strong>⌘+H</strong> / <strong>Ctrl+H</strong> opens it with the replace row, which has <strong>Replace</strong> for the current match and <strong>All</strong> for every match.</li><li>Two toggles narrow the search: <strong>Match case</strong> and <strong>Use regex</strong>.</li></ul><p>The replace row is hidden when you only have read access to the document.</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p>Insert a table from the toolbar to lay out structured content. Click the <strong>Table</strong> button, drag to pick the grid size, and the table appears at the cursor.</p><ul><li><strong>Tab</strong> moves between cells (Shift+Tab moves backward).</li><li>Right-click a cell for row and column operations — insert above/below, insert left/right, delete row/column, and delete the table.</li><li>To combine cells, select a rectangle of them and choose <strong>Merge cells</strong> from the same menu. Right-clicking a merged cell offers <strong>Unmerge cells</strong> instead, which puts the original cells back. (There is no way to divide a cell that was never merged.)</li><li>Drag a column or row border to resize.</li><li>Tables can be nested — insert a table inside a cell to build sub-grids.</li></ul><p>When a table is taller than the remaining space on a page, its rows split across the page boundary automatically.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Click the <strong>Insert image</strong> button in the toolbar and choose:</p><ul><li><strong>Upload from computer</strong> — pick an image file from your device.</li><li><strong>By URL…</strong> — paste the address of an image on the web.</li></ul><p>You can also drag an image file straight onto the page, or paste one copied from another app.</p><p>Once an image is placed, click it to select it. Eight square handles appear around the edges:</p><ul><li>Drag a <strong>corner</strong> handle to resize while keeping the aspect ratio (hold <strong>Shift</strong> to resize freely).</li><li>Drag a <strong>side</strong> handle to stretch one dimension.</li><li><strong>Delete</strong> / <strong>Backspace</strong> removes it; <strong>Esc</strong> deselects and puts the cursor back where the image sits.</li><li><strong>Arrow keys</strong> leave the image and move the text cursor, as they do in Google Docs: <strong>←</strong> places the cursor just before the image, <strong>→</strong> just after, and <strong>↑</strong> / <strong>↓</strong> move by line. Images sit inline in the text, so there is no free positioning to nudge them to.</li></ul><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><p>Documents use a page-based layout similar to a printed document. Pages default to Letter with 1-inch margins, and text flows across pages as you type.</p><ul><li>Long paragraphs and tables break naturally at the page boundary — line splitting keeps headings, table headers, and partial rows in sync with the layout.</li><li>The editor renders one page per &quot;sheet&quot; so you can scroll through the deck of pages exactly as they will print or export.</li><li>Export to PDF preserves the same pagination — what you see on screen matches the exported document.</li></ul><p>To end a page early, press <strong>⌘+Enter</strong> / <strong>Ctrl+Enter</strong> to insert a page break. Everything after the cursor moves to the top of the next page.</p><h3 id="page-setup" tabindex="-1">Page Setup <a class="header-anchor" href="#page-setup" aria-label="Permalink to &quot;Page Setup&quot;">​</a></h3><p>Click <strong>Page setup</strong> in the toolbar (on a phone, it is in the <strong>⋮</strong> overflow menu) to change:</p><ul><li><strong>Paper size</strong> — Letter, A4, or Legal.</li><li><strong>Orientation</strong> — portrait or landscape.</li><li><strong>Margins</strong> — top, bottom, left, and right, in inches.</li></ul><p>The change applies to the whole document and is a single undo step. You can also drag the margin markers on the ruler to adjust margins directly.</p><h2 id="headers-footers" tabindex="-1">Headers &amp; Footers <a class="header-anchor" href="#headers-footers" aria-label="Permalink to &quot;Headers &amp; Footers&quot;">​</a></h2><p>Add content that repeats on every page — a title, a date, or a page number.</p><ul><li><strong>Double-click</strong> the margin area above the body (header) or below it (footer) to start editing it. Click back into the body, or press <strong>Esc</strong>, to leave.</li><li>While editing a header or footer, click <strong>Insert page number</strong> in the toolbar to drop in a number that updates automatically on each page.</li></ul><p>A header or footer applies to the whole document, and the toolbar narrows while you edit one — bold, italic, underline, colors, alignment, and the page-number button, but no lists, links, or styles dropdown. You can&#39;t insert a table, a page break, or a horizontal rule into a header or footer.</p><p>A table that arrives inside a header or footer through <strong>DOCX import</strong> — a common letterhead pattern — is kept and drawn correctly. It just isn&#39;t editable in place: clicking it moves the cursor to the nearest editable paragraph instead.</p><h2 id="spell-check" tabindex="-1">Spell Check <a class="header-anchor" href="#spell-check" aria-label="Permalink to &quot;Spell Check&quot;">​</a></h2><p>Misspelled words are underlined with a red squiggle as you type — spell check is on by default. Right-click an underlined word to see suggestions and click one to replace it.</p><p>Spell check currently covers English (Latin-script) words in the body text.</p><h2 id="the-right-click-menu" tabindex="-1">The Right-Click Menu <a class="header-anchor" href="#the-right-click-menu" aria-label="Permalink to &quot;The Right-Click Menu&quot;">​</a></h2><p>Right-clicking in the body opens one menu that gathers whatever applies where you clicked:</p><ul><li><strong>Spelling suggestions</strong> for a word with a red squiggle under it.</li><li><strong>Cut</strong>, <strong>Copy</strong>, and <strong>Paste</strong>.</li><li><strong>Add link</strong>, and <strong>Insert comment</strong> when text is selected.</li></ul><p>Right-clicking inside a table opens the table menu instead — see <a href="#tables">Tables</a> above.</p><h2 id="comments" tabindex="-1">Comments <a class="header-anchor" href="#comments" aria-label="Permalink to &quot;Comments&quot;">​</a></h2><p>Select text and press <strong>⌘+Option+M</strong> / <strong>Ctrl+Alt+M</strong> to start a comment, or right-click and choose <strong>Insert comment</strong>. A document comment needs a real selection — nothing happens with a bare cursor.</p><p>Replies, resolving, mentions, and the comments panel are covered in <a href="/docs/guide/collaboration.html#comments-mentions">Collaboration &amp; Sharing</a>.</p><h2 id="undo-and-redo" tabindex="-1">Undo and Redo <a class="header-anchor" href="#undo-and-redo" aria-label="Permalink to &quot;Undo and Redo&quot;">​</a></h2><ul><li><strong>⌘+Z</strong> / <strong>Ctrl+Z</strong> — Undo the last action</li><li><strong>⌘+Shift+Z</strong> / <strong>Ctrl+Y</strong> — Redo</li></ul><p>You can also use the undo/redo buttons in the toolbar.</p><h2 id="see-every-shortcut" tabindex="-1">See Every Shortcut <a class="header-anchor" href="#see-every-shortcut" aria-label="Permalink to &quot;See Every Shortcut&quot;">​</a></h2><p>Press <strong>⌘+/</strong> / <strong>Ctrl+/</strong> anywhere in the editor to open the shortcuts dialog. The dialog is maintained alongside the editor&#39;s bindings rather than derived from them, but it currently matches <a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a> entry for entry. <strong>Esc</strong> closes it.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a> — Full list of document editor shortcuts</li><li><a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a> — Share and edit documents together in real time</li></ul>',89)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
